def verdict(r,direction=+1):
    ok_dir=(r.ratio>1) if direction>0 else (r.ratio<1)
    sig=(r.ci_lo>1) if direction>0 else (r.ci_hi<1); opp=(r.ci_hi<1) if direction>0 else (r.ci_lo>1)
    rep=r.ch_pos/r.ch_tot if r.ch_tot else np.nan
    rep_dir=rep if direction>0 else 1-rep if r.ch_tot else np.nan
    if sig and (r.ch_tot<10 or rep_dir>=.6): return 'Supported'
    if sig: return 'Mixed (pooled effect, weak per-channel replication)'
    if opp: return 'Contradicted'
    return 'Mixed (no detectable effect)' if ok_dir else 'Mixed (no detectable effect; direction opposite)'
def conf(r):
    n=min(r.n_with,r.n_without); return 'Moderate' if n>=300 and r.ch_tot>=20 else 'Low-Moderate' if n>=100 else 'Low'
