    rows.append(dict(Source=r.source,Principle=r.claim,Dataset_Evidence=ev,Result=verdict(r,d),Confidence=conf(r),Predicted_direction='lower' if d<0 else 'higher',Notes='Regex/lexical proxy of the principle; see methodology limits.'))
